class Solution {
    public int checkWays(int[][] pairs){
        Map<Integer,Set<Integer>> graph=new HashMap<>();
        for(int[] pair:pairs){
            graph.computeIfAbsent(pair[0],key->new HashSet<>()).add(pair[1]);
            graph.computeIfAbsent(pair[1],key->new HashSet<>()).add(pair[0]);
        }
        int root=-1;
        for(int node:graph.keySet())if(graph.get(node).size()==graph.size()-1){
            root=node;
            break;
        }
        if(root<0)return 0;
        int answer=1;
        for(int node:graph.keySet()){
            if(node==root)continue;
            int degree=graph.get(node).size(),parent=-1,parentDegree=Integer.MAX_VALUE;
            for(int neighbor:graph.get(node)){
                int candidateDegree=graph.get(neighbor).size();
                if(candidateDegree>=degree&&candidateDegree<parentDegree){
                    parent=neighbor;
                    parentDegree=candidateDegree;
                }
            }
            if(parent<0)return 0;
            for(int neighbor:graph.get(node))if(neighbor!=parent&&!graph.get(parent).contains(neighbor))return 0;
            if(parentDegree==degree)answer=2;
        }
        return answer;
    }
}

